          "stageDirection": "Mouvement de danse très rapide, très violent. — Carmen elle-même danse et vient, avec les dernières notes de l’orchestre, tomber haletante sur un banc. — Après la danse, Lillas Pastia se met à tourner autour des officiers d’un air embarrassé.",
          "stageDirectionTranslation": "Very rapid, very violent dance movement. Carmen herself dances and comes, with the last notes of the orchestra, to fall panting upon a bench. After the dance, Lillas Pastia begins to circle around the officers with an embarrassed air."
