              "id": "a2_s4_c8_l1",
              "original": "Taisez-vous alors… Nous arrivons de Gibraltar, nous avons arrangé avec un patron de navire, le débarquement de marchandises anglaises. Nous irons les attendre près de la côte, nous en cacherons une partie dans la montagne et nous ferons passer le reste… Tous nos camarades ont été prévenus… ils sont ici, cachés… mais c’est de vous trois surtout que nous avons besoin… vous allez partir avec nous…",
              "literal": "Be silent then... We arrive from Gibraltar, we have arranged with a ship captain the landing of English goods. We will go wait for them near the coast, we will hide part of them in the mountain and we will pass the rest... All our comrades have been alerted... they are here, hidden... but it is you three above all that we need... you are going to leave with us...",
