              "original": "Ah bien !… Canari, va !… tu es un vrai canari, d’habit et de caractère… Allons, ne te fâche pas… Pourquoi es-tu jaloux ? parce que j’ai dansé tout à l’heure pour ces officiers… eh bien, si tu le veux, je danserai pour toi maintenant, pour toi tout seul.",
