          "stageDirection": "Elle recommence à fredonner son air qui se rythme sur la retraite sonnée au dehors par les clairons ; elle se remet à danser et José se remet à la regarder. La retraite approche… approche… approche… passe sous les fenêtres de l’auberge… puis s’éloigne… Le son des clairons va s’affaiblissant. Nouvel effort de José pour s’arracher à cette contemplation de Carmen. Il lui prend le bras et l’oblige encore à s’arrêter.",
          "stageDirectionTranslation": "She begins again to hum her air rhythmically to the retreat sounded outside by the bugles; she resumes dancing and José resumes watching her. The retreat approaches... passes under the inn windows... then moves off... Bugle sounds weaken. New effort by José to tear himself away from this contemplation. He takes her arm and forces her again to stop."
